add_shortcode( 'spoiler', 'perfectpixel_spoiler_shortcode' );

function perfectpixel_spoiler_shortcode( $atts, $content = '' ) {
	static $assets_done = false;
	$html = '';
	if ( ! $assets_done ) {
		$assets_done = true;
		$html       .= '<style>.perfectpixel-spoiler{background:#1d2327;color:transparent;border-radius:2px;cursor:pointer;transition:color .2s,background .2s}.perfectpixel-spoiler *{visibility:hidden}.perfectpixel-spoiler.is-revealed{background:rgba(0,0,0,.06);color:inherit}.perfectpixel-spoiler.is-revealed *{visibility:visible}</style>';
		$html       .= '<script>document.addEventListener( "click", function ( e ) { var s = e.target.closest ? e.target.closest( ".perfectpixel-spoiler" ) : null; if ( s ) { s.classList.toggle( "is-revealed" ); s.setAttribute( "aria-pressed", s.classList.contains( "is-revealed" ) ? "true" : "false" ); } } ); document.addEventListener( "keydown", function ( e ) { if ( ( e.key === "Enter" || e.key === " " ) && e.target.classList && e.target.classList.contains( "perfectpixel-spoiler" ) ) { e.preventDefault(); e.target.click(); } } );</script>';
	}
	return $html . '<span class="perfectpixel-spoiler" role="button" tabindex="0" aria-pressed="false" title="' . esc_attr( '{{spoiler_label}}' ) . '">' . do_shortcode( $content ) . '</span>';
}
